#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    bool isPreorder(vector<vector<int>>& nodes) {
        if (nodes.empty() || nodes[0][1] != -1) return false;
        unordered_set<int> seen;
        vector<int> ancestors;
        for (auto& node : nodes) {
            int id = node[0], parent = node[1];
            if (!seen.insert(id).second) return false;
            while (!ancestors.empty() && ancestors.back() != parent) ancestors.pop_back();
            if (parent != -1 && ancestors.empty()) return false;
            if (parent == -1 && !ancestors.empty()) return false;
            ancestors.push_back(id);
        }
        return true;
    }
};
